package Cx

import data.generic.ansible as ansLib

is_enc_alg_field(field) {
	fields := {
		"algorithm", "cipher", "cipher_suite", "encryption_algorithm",
		"server_side_encryption", "sse_algorithm", "encryption_type", "encryption_method",
	}
	fields[field]
}

is_tls_version_field(field) {
	fields := {
		"minimum_tls_version", "min_tls_version", "tls_version",
		"ssl_policy", "security_policy", "ssl_protocol",
		"protocol_version", "tls_policy",
	}
	fields[field]
}

is_hash_alg_field(field) {
	fields := {
		"hash_algorithm", "signing_algorithm", "digest_algorithm",
		"key_algorithm", "signature_algorithm", "checksum_algorithm",
	}
	fields[field]
}

is_curve_field(field) {
	fields := {"curve", "elliptic_curve", "curve_name", "ec_curve", "key_curve", "named_curve"}
	fields[field]
}

is_key_size_field(field) {
	fields := {"key_size", "key_length", "rsa_bits", "key_bits", "size", "modulus_length", "bit_length"}
	fields[field]
}

is_vpn_enc_field(field) {
	fields := {
		"phase1_encryption_algorithms", "phase2_encryption_algorithms",
		"ike_encryption", "tunnel_encryption",
	}
	fields[field]
}

is_weak_cipher(value) {
	weak := {"des", "3des", "tripledes", "triple_des", "rc2", "rc4", "rc5", "idea", "blowfish"}
	weak[lower(value)]
}

is_weak_tls(value) {
	weak := {
		"sslv2", "sslv3", "ssl2", "ssl3",
		"tlsv1", "tlsv1.0", "tlsv1.1",
		"tls_1_0", "tls_1_1", "tls1.0", "tls1.1",
	}
	weak[lower(value)]
}

is_weak_tls(value) {
	patterns := {"tls-1-0", "tls-1-1", "sslv3", "ssl3.0", "policy-min-tls-1-0"}
	contains(lower(value), patterns[_])
}

is_weak_hash(value) {
	weak := {"md5", "md4", "md2", "sha1", "sha-1", "sha_1", "hmac-md5", "hmac-sha1"}
	weak[lower(value)]
}

is_weak_curve(value) {
	weak := {"p-192", "secp192r1", "prime192v1", "p-224", "secp224r1", "b-163", "k-163"}
	weak[lower(value)]
}

# CWE-326: Weak encryption algorithm in module parameters
CxPolicy[result] {
	task := ansLib.tasks[id][t]
	walk(task, [path, value])
	count(path) == 2
	is_enc_alg_field(path[1])
	is_string(value)
	is_weak_cipher(value)

	result := {
		"documentId": id,
		"resourceType": path[0],
		"resourceName": task.name,
		"searchKey": sprintf("name={{%s}}.{{%s}}.%s", [task.name, path[0], path[1]]),
		"issueType": "IncorrectValue",
		"keyExpectedValue": sprintf("'%s' should use a strong encryption algorithm (e.g., AES-256)", [path[1]]),
		"keyActualValue": sprintf("'%s' is set to weak algorithm '%s'", [path[1], value]),
	}
}

# CWE-326: Weak encryption algorithm in VPN/IPSec phase arrays
CxPolicy[result] {
	task := ansLib.tasks[id][t]
	walk(task, [path, value])
	count(path) == 3
	is_vpn_enc_field(path[1])
	is_string(value)
	is_weak_cipher(value)

	result := {
		"documentId": id,
		"resourceType": path[0],
		"resourceName": task.name,
		"searchKey": sprintf("name={{%s}}.{{%s}}.%s", [task.name, path[0], path[1]]),
		"issueType": "IncorrectValue",
		"keyExpectedValue": sprintf("'%s' should not include weak encryption algorithms", [path[1]]),
		"keyActualValue": sprintf("'%s' includes weak algorithm '%s'", [path[1], value]),
	}
}

# CWE-326: Deprecated TLS/SSL protocol version
CxPolicy[result] {
	task := ansLib.tasks[id][t]
	walk(task, [path, value])
	count(path) == 2
	is_tls_version_field(path[1])
	is_string(value)
	is_weak_tls(value)

	result := {
		"documentId": id,
		"resourceType": path[0],
		"resourceName": task.name,
		"searchKey": sprintf("name={{%s}}.{{%s}}.%s", [task.name, path[0], path[1]]),
		"issueType": "IncorrectValue",
		"keyExpectedValue": sprintf("'%s' should use TLS 1.2 or higher", [path[1]]),
		"keyActualValue": sprintf("'%s' is set to deprecated protocol '%s'", [path[1], value]),
	}
}

# CWE-326: Weak hash or signing algorithm
CxPolicy[result] {
	task := ansLib.tasks[id][t]
	walk(task, [path, value])
	count(path) == 2
	is_hash_alg_field(path[1])
	is_string(value)
	is_weak_hash(value)

	result := {
		"documentId": id,
		"resourceType": path[0],
		"resourceName": task.name,
		"searchKey": sprintf("name={{%s}}.{{%s}}.%s", [task.name, path[0], path[1]]),
		"issueType": "IncorrectValue",
		"keyExpectedValue": sprintf("'%s' should use a strong hash algorithm (e.g., SHA-256 or higher)", [path[1]]),
		"keyActualValue": sprintf("'%s' is set to weak hash algorithm '%s'", [path[1], value]),
	}
}

# CWE-326: Weak elliptic curve
CxPolicy[result] {
	task := ansLib.tasks[id][t]
	walk(task, [path, value])
	count(path) == 2
	is_curve_field(path[1])
	is_string(value)
	is_weak_curve(value)

	result := {
		"documentId": id,
		"resourceType": path[0],
		"resourceName": task.name,
		"searchKey": sprintf("name={{%s}}.{{%s}}.%s", [task.name, path[0], path[1]]),
		"issueType": "IncorrectValue",
		"keyExpectedValue": sprintf("'%s' should use a strong elliptic curve (e.g., P-256, P-384, or P-521)", [path[1]]),
		"keyActualValue": sprintf("'%s' is set to weak curve '%s'", [path[1], value]),
	}
}

# CWE-326: Insufficient RSA/DSA key size (< 2048 bits)
CxPolicy[result] {
	task := ansLib.tasks[id][t]
	walk(task, [path, value])
	count(path) == 2
	is_key_size_field(path[1])
	is_number(value)
	value < 2048

	module := task[path[0]]
	is_object(module)
	key_type := object.get(module, "type", "RSA")
	not contains(lower(key_type), "ec")

	result := {
		"documentId": id,
		"resourceType": path[0],
		"resourceName": task.name,
		"searchKey": sprintf("name={{%s}}.{{%s}}.%s", [task.name, path[0], path[1]]),
		"issueType": "IncorrectValue",
		"keyExpectedValue": sprintf("'%s' should be at least 2048 bits for RSA/DSA keys", [path[1]]),
		"keyActualValue": sprintf("'%s' is set to %d bits which is below the recommended minimum", [path[1], value]),
	}
}

