    {
      "apt": "name=curl state=present",
      "name": "Restore Service | Install 'curl'"
    },
    {
      "name": "Restore Service | Set variables",
      "set_fact": {
        "restore_service_password": "{{ restore_service.pass }}",
        "restore_service_username": "{{ restore_service.user | hash('sha1') }}"
      }
    },
