	is_string(value)
	weak := {"des", "3des", "triple_des", "tripledes", "rc2", "rc4", "rc5", "idea", "blowfish", "md5", "md4", "md2", "sha1", "sha-1", "sha_1"}
	lower(value) == weak[_]
